query:
NODE VALUE incoming_sum SumAgg<INT64> = 0
TABLE results {id STRING, total INT64}

MATCH (s:player)-[e:follow]->(t:player)
PER PATH {
  SET t.@incoming_sum += coalesce(e.degree, 0)
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id AS id, p.@incoming_sum AS total INTO results
}

FOR r IN results
RETURN r.id AS id, r.total AS total
